CREATE OR REPLACE FUNCTION public.task_child_integrity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.tasks WHERE id=new.task_id AND project_id=new.project_id) THEN RAISE EXCEPTION 'Task does not belong to this project'; END IF; IF tg_table_name='task_labels' THEN IF NOT EXISTS(SELECT 1 FROM public.labels WHERE id=new.label_id AND project_id=new.project_id) THEN RAISE EXCEPTION 'Label does not belong to this project'; END IF; END IF; RETURN new; END $$;